from typing import List, Dict, Any

class TextModerationRequest:
    def __init__(self, text: str):
        self.text = text

class TextModerationResponse:
    def __init__(self, categories: Dict[str, float], is_unsafe: bool):
        self.categories = categories
        self.is_unsafe = is_unsafe

class BatchModerationRequest:
    def __init__(self, texts: List[str]):
        self.texts = texts

class BatchModerationResponse:
    def __init__(self, results: List[TextModerationResponse]):
        self.results = results

class RedactionRequest:
    def __init__(self, text: str):
        self.text = text

class RedactionResponse:
    def __init__(self, redacted_text: str, unsafe_spans: List[Dict[str, Any]]):
        self.redacted_text = redacted_text
        self.unsafe_spans = unsafe_spans

class ThresholdConfig:
    def __init__(self, thresholds: Dict[str, float], decision_threshold: float = 0.5):
        self.thresholds = thresholds
        self.decision_threshold = decision_threshold

class ThresholdDecision:
    def __init__(self, is_allowed: bool, decision_details: Dict[str, Any]):
        self.is_allowed = is_allowed
        self.decision_details = decision_details

import boto3
from typing import Dict, Any

def get_aws_comprehend_client():
    return boto3.client('comprehend')

def parse_aws_comprehend_moderation_response(response: Dict[str, Any]) -> Dict[str, float]:
    categories = {}
    for result in response.get('ModerationLabels', []):
        name = result.get('Name')
        score = result.get('Score')
        if name and score:
            categories[name] = score
    return categories

from typing import List
from safety_models import BatchModerationRequest, BatchModerationResponse, TextModerationResponse
from moderate_text import moderate_text

def moderate_batch(request: BatchModerationRequest) -> BatchModerationResponse:
    results: List[TextModerationResponse] = []
    for text in request.texts:
        individual_request = TextModerationRequest(text=text)
        result = moderate_text(individual_request)
        results.append(result)
    return BatchModerationResponse(results=results)

from safety_models import TextModerationResponse, ThresholdConfig, ThresholdDecision
from typing import Dict, Any

def apply_safety_thresholds(moderation_response: TextModerationResponse, config: ThresholdConfig) -> ThresholdDecision:
    is_allowed = True
    decision_details: Dict[str, Any] = {}

    for category, score in moderation_response.categories.items():
        threshold = config.thresholds.get(category, config.decision_threshold)
        if score >= threshold:
            is_allowed = False
            decision_details[category] = {"score": score, "threshold": threshold, "exceeded": True}
        else:
            decision_details[category] = {"score": score, "threshold": threshold, "exceeded": False}

    if moderation_response.is_unsafe:
        is_allowed = False
        decision_details["overall_unsafe_flag"] = {"is_unsafe_flagged": True}

    return ThresholdDecision(is_allowed=is_allowed, decision_details=decision_details)
